//! Staging-only anonymous transport discriminator; never a public mail command.

use reqwest::blocking::Client;
use std::{
    io::{self, Read},
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::Duration,
};
use url::Url;

/// Permit exactly the synthetic protected URL generated by the hosted harness.
fn valid_target(raw: &str) -> Option<Url> {
    let url = Url::parse(raw).ok()?;
    let path = url.path().strip_prefix("/v1/messages/amail_path_canary_")?;
    let marker = path;
    if url.scheme() != "https"
        || url.host_str() != Some("mail-staging.moesegfault.dev")
        || url.port().is_some()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.fragment().is_some()
        || marker.len() != 32
        || !marker
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        || url.query() != Some(format!("probe=amail_query_canary_{marker}").as_str())
    {
        return None;
    }
    Some(url)
}

/// Match amail's reqwest blocking client and report only reviewed response facts.
fn probe(url: Url) -> Option<String> {
    let redirected = Arc::new(AtomicBool::new(false));
    let observed = Arc::clone(&redirected);
    let client = Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::redirect::Policy::custom(move |attempt| {
            observed.store(true, Ordering::Relaxed);
            attempt.stop()
        }))
        .build()
        .ok()?;
    let response = client.get(url).send().ok()?;
    let status = response.status().as_u16();
    let request_id = response.headers().get_all("x-amail-request-id");
    let valid_id = request_id.iter().count() == 1
        && request_id
            .iter()
            .next()
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| {
                uuid::Uuid::parse_str(value).is_ok_and(|id| id.hyphenated().to_string() == value)
            });
    let ray = response.headers().get_all("cf-ray");
    let ray_present =
        ray.iter().count() == 1 && ray.iter().next().is_some_and(|value| !value.is_empty());
    let status_label = match status {
        401 => "401",
        403 => "403",
        300..=399 => "3xx",
        200..=299 => "2xx",
        400..=499 => "other_4xx",
        500..=599 => "5xx",
        _ => "other",
    };
    Some(format!(
        "status={status_label} id={valid_id} ray={ray_present} redirect={}",
        redirected.load(Ordering::Relaxed)
    ))
}

/// Consume the URL on stdin so no synthetic marker appears in process arguments.
fn main() {
    let mut raw = String::new();
    if io::stdin().take(256).read_to_string(&mut raw).is_err() {
        println!("staging_http_compare: unverified");
        std::process::exit(1);
    }
    let result = valid_target(raw.trim_end_matches(['\r', '\n'])).and_then(probe);
    match result {
        Some(facts) => println!("staging_http_compare: {facts}"),
        None => {
            println!("staging_http_compare: unverified");
            std::process::exit(1);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::valid_target;

    /// No arbitrary host, route, marker, fragment, or query can be probed.
    #[test]
    fn target_is_exact_staging_synthetic_route() {
        let marker = "a".repeat(32);
        let good = format!("https://mail-staging.moesegfault.dev/v1/messages/amail_path_canary_{marker}?probe=amail_query_canary_{marker}");
        assert!(valid_target(&good).is_some());
        for bad in [
            good.replace("mail-staging", "mail"),
            good.replace("?probe=", "?other="),
            good.replace("amail_query_canary_a", "amail_query_canary_b"),
            format!("{good}#private"),
        ] {
            assert!(valid_target(&bad).is_none());
        }
    }
}
